26	        String postcode = request.getPostcode();
27	        if (postcode == null || postcode.isEmpty()) {
28	            return; // optional when absent
29	        }
30	        String region = Owner.regionOf(request.getCity());
31	        if (region == null) {
32	            return; // city with no known region accepts any 4-digit postcode
33	        }
