35	        int value = Integer.parseInt(postcode); // 4-digit shape guaranteed by the DTO pattern
36	        if (value < range[0] || value > range[1]) {
37	            throw new InvalidPostcodeException(
38	                "Postcode " + postcode + " is not valid for city " + request.getCity());
